"},{"block_id":"M050-SRC-047-SURVIVORSHIP-REVIEW-001__B00105_a66e2bdbbd90","block_type":"paragraph","estimated_claims":1,"parent_heading":"### Required ruling","status_markers":[],"text":"<!--@3.1.4¶4-->
